ranked = ["weighting#caps", "weighting#w14", "sampling#bases", "weighting#targets"]
relevant = {"weighting#w14", "weighting#targets"}


def recall_at_k(ranked, relevant, k):
    return len(set(ranked[:k]) & relevant) / len(relevant)


def reciprocal_rank(ranked, relevant):
    for rank, item in enumerate(ranked, start=1):
        if item in relevant:
            return 1 / rank
    return 0.0


print(recall_at_k(ranked, relevant, 2), recall_at_k(ranked, relevant, 4), reciprocal_rank(ranked, relevant))

